INSERT INTO p_studio_batch (id, act_id, num, br_batch_id, name, brief_json, setup_json, plan_json, status) VALUES ('cb4dc58058d41012ced078c5', 'brand_ice_and_gold', NULL, NULL, 'Early Bird: free studs over $125 (real photos)', '{"angle": "Early Bird (Nov 2 to 25): free studs on any order over $125, everything else full price; no list-building ads (the list hears about early access by email and SMS).", "why": "Locked with Fela Oct 13 (her AOV is ~$125). Offer statics were the account best ads on TW (summer sale 6.5x, catalog 3.75x); plain product statics lost (0.07x). 60% of customers come back, so the list is the asset.", "concept": "Real iceandgold.com photos only (Fela). Product leads, the studs are the second line. Every line already has its finished image. Studs are not pictured (new listing in about 2 weeks).", "post_copy": "Free studs on any order over $125, Nov 2 to 25. 18K gold over stainless steel, made to wear every day. 1-year warranty.", "testing": "concepts", "lines": [{"text": "eb-01: The Gold Link Set leads, studs second. Product leads, gift is line two (2025 lesson: leading with the gift lost). Testing: the account winner (Adeola Gold Link Set, 4.77x TW) as an offer static.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7905f645248311a8928a0f61.png"}, {"text": "eb-02: A heart she will wear every day. Lariat Heart Set $169 on cream. Testing: gift-giver line on a product shot.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/92142135b894b8f0d2f3f5d3.png"}, {"text": "eb-03: This set comes with free studs. Spiral Set $149 clears $125 on its own. Testing: one piece that unlocks the gift.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/96535d4cdfb9d07a4c3b9aaf.png"}, {"text": "eb-04: The Water Drop Set. $129. That is over $125, so the studs are free. Testing: the threshold anchored to the cheapest set over it.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/5f45e27939fec4b069a36e0d.png"}, {"text": "eb-05: Two gifts on your list. A free pair of studs for you. Gold Link Earrings $79 + Gold Letter Pendant $89. Testing: two-piece basket for the gift buyer.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7a1ed4009f43c8b946dfdc36.png"}, {"text": "eb-06: Wear it every day. It stays gold. 18K gold over stainless steel, tarnish free, sweat proof, will not turn your skin green. Testing: proof + offer.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6b1c118adc6f8fc0e47f9793.png"}, {"text": "eb-07: Review over product: \"The packaging was as impressive as the necklace itself.\" (Zaylee, iceandgold.com). Testing: packaging as the gift reason.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3649722801c18273fb091292.png"}, {"text": "eb-08: His chain is on your list. 12mm Diamond Clasps Gold Cuban Set $249, the free studs are for you. Testing: a men2019s gift to the woman buying it.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6f6b8ffbe8579ac17dad384a.png"}, {"text": "eb-09: Native Notes app: Christmas list (Mom, Sis, Auntie, Me: the free studs). Testing: native format, never tested on this account.", "inspo": [], "photo": "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3684aefc1fd80f42c94ec6cf.png"}], "source": "Ice & Gold BFCM ads chat, 2026-10-14 (docs/bfcm-ice-and-gold-concepts.md, Batch 1)", "reference": "docs/bfcm-ice-and-gold-concepts.md"}', '{"products": [], "images": ["https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7905f645248311a8928a0f61.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/92142135b894b8f0d2f3f5d3.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/96535d4cdfb9d07a4c3b9aaf.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/5f45e27939fec4b069a36e0d.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/7a1ed4009f43c8b946dfdc36.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6b1c118adc6f8fc0e47f9793.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3649722801c18273fb091292.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/6f6b8ffbe8579ac17dad384a.png", "https://mobius-profit.mobius-digital.workers.dev/api/studio/ref/3684aefc1fd80f42c94ec6cf.png"], "swipe": []}', NULL, 'draft');
